func (this *Menu) gtk_menu_popped_up_(widget int64, flipped_rect int64, final_rect int64, flipped_x int64, flipped_y int64) int64 {
	var finalRect gtk.GdkRectangle = gtk.GdkRectangle{}
	gtk.OSMemmoveOverload13(&finalRect, final_rect, int64(gtk.GDKGdkRectangle_sizeof()))
	var flippedRect gtk.GdkRectangle = gtk.GdkRectangle{}
	gtk.OSMemmoveOverload13(&flippedRect, flipped_rect, int64(gtk.GDKGdkRectangle_sizeof()))
	var flippedX bool = flipped_x == 1
	var flippedY bool = flipped_y == 1
	fmt.Fprintln(os.Stdout, fmt.Sprintf("SWT_MENU_LOCATION_DEBUGGING enabled, printing positioning info for %d", widget))
	if gtk.OSIsWayland() {
		fmt.Fprintln(os.Stdout, "Note: SWT is running on Wayland, coordinates will be parent-relative")
	}
	if this.hasLocation {
		fmt.Fprintln(os.Stdout, fmt.Sprintf("hasLocation is true and set coordinates are Point {%d, %d}", this.x, this.y))
	} else {
		fmt.Fprintln(os.Stdout, "hasLocation is not set, this is most likely a right click menu")
	}
	if flippedX {
		fmt.Fprintln(os.Stdout, "Menu is inverted along the X-axis")
	}
	if flippedY {
		fmt.Fprintln(os.Stdout, "Menu is inverted along the Y-axis")
	}
	fmt.Fprintln(os.Stdout, fmt.Sprintf("Final menu position and size is Rectangle {%d, %d, %d, %d}", finalRect.X, finalRect.Y, finalRect.Width, finalRect.Height))
	fmt.Fprintln(os.Stdout, fmt.Sprintf("Flipped menu position and size is Rectangle {%d, %d, %d, %d}", flippedRect.X, flippedRect.Y, flippedRect.Width, flippedRect.Height))
	fmt.Fprintln(os.Stdout, "")
	return int64(0)
}

func (this *Menu) hookEvents_() {
	this.Widget.hookEvents_()
	if gtk.GTKGTK4 {
		this.shortcutController = gtk.GTK4Gtk_shortcut_controller_new()
		if this.shortcutController == 0 {
			this.Error(ERROR_NO_HANDLES)
		}
		gtk.GTK4Gtk_shortcut_controller_set_scope(this.shortcutController, gtk.GTKGTK_SHORTCUT_SCOPE_GLOBAL)
		gtk.GTK4Gtk_widget_add_controller(this.parent.Handle, this.shortcutController)
		this.HookItemsChanged(this.modelHandle)
		if this.sections != (nil) && !this.sections.IsEmpty() {
			this.HookItemsChanged(jrt.Cast[*Menu_Section](this.sections.GetFirst()).GetSectionHandle())
		}
		if (this.style & DROP_DOWN) == 0 {
			gtk.OSG_signal_connect_closure_by_id(this.Handle, this.display.signalIds[WidgetSHOW], 0, this.display.GetClosure(WidgetSHOW), false)
			gtk.OSG_signal_connect_closure_by_id(this.Handle, this.display.signalIds[WidgetHIDE], 0, this.display.GetClosure(WidgetHIDE), false)
			if (this.style & (BAR | POP_UP)) != 0 {
				gtk.OSG_signal_connect_closure_by_id(this.Handle, this.display.signalIds[WidgetMAP], 0, this.display.GetClosure(WidgetMAP), false)
			}
		}
	} else {
		gtk.OSG_signal_connect_closure_by_id(this.Handle, this.display.signalIds[WidgetSHOW_HELP], 0, this.display.GetClosure(WidgetSHOW_HELP), false)
		if gtk.OSSWT_MENU_LOCATION_DEBUGGING {
			gtk.OSG_signal_connect_closure_by_id(this.Handle, this.display.signalIds[WidgetPOPPED_UP], 0, this.display.GetClosure(WidgetPOPPED_UP), false)
		}
		gtk.OSG_signal_connect_closure_by_id(this.Handle, this.display.signalIds[WidgetSHOW], 0, this.display.GetClosure(WidgetSHOW), false)
		gtk.OSG_signal_connect_closure_by_id(this.Handle, this.display.signalIds[WidgetHIDE], 0, this.display.GetClosure(WidgetHIDE), false)
	}
}

