func (this *Menu) AdjustParentWindowWayland(eventPtr int64) {
	if gtk.OSIsWayland() {
		var display int64 = gtk.GDKGdk_display_get_default()
		var pointer int64 = gtk.GDKGdk_get_pointer(display)
		var deviceResource int64
		if gtk.GTKGTK4 {
			deviceResource = gtk.GDKGdk_device_get_surface_at_position(pointer, nil, nil)
		} else {
			deviceResource = gtk.GDKGdk_device_get_window_at_position(pointer, nil, nil)
		}
		gtk.OSG_object_ref(deviceResource)
		var eventType int32 = gtk.GDKGdk_event_get_event_type(eventPtr)
		switch eventType {
		case gtk.GDKGDK_BUTTON_PRESS:
			var eventButton gtk.GdkEventButton = gtk.GdkEventButton{}
			gtk.GTK3Memmove(&eventButton, eventPtr, int64(gtk.GdkEventButtonSizeof))
			eventButton.Window = deviceResource
			gtk.GTK3MemmoveOverload6(eventPtr, &eventButton, int64(gtk.GdkEventButtonSizeof))
			break
		case gtk.GDKGDK_KEY_PRESS:
			var eventKey gtk.GdkEventKey = gtk.GdkEventKey{}
			gtk.GTK3MemmoveOverload3(&eventKey, eventPtr, int64(gtk.GdkEventKeySizeof))
			eventKey.Window = deviceResource
			gtk.GTK3MemmoveOverload7(eventPtr, &eventKey, int64(gtk.GdkEventKeySizeof))
			break
		}
	}
	return
}

func (this *Menu) VerifyMenuPosition(itemCount int32) {
	if gtk.OSIsX11() {
		if itemCount != this.poppedUpCount && this.poppedUpCount != 0 {
			var naturalHeight []int32 = make([]int32, 1)
			this.Gtk_widget_show(this.Handle)
			gtk.GTK3Gtk_widget_get_preferred_height(this.Handle, nil, naturalHeight)
			if naturalHeight[0] > 0 {
				if gtk.GTKGTK4 {
				} else {
					var topLevelWidget int64 = gtk.GTK3Gtk_widget_get_toplevel(this.Handle)
					var topLevelWindow int64 = gtk.GTK3Gtk_widget_get_window(topLevelWidget)
					var width int32 = gtk.GDKGdk_window_get_width(topLevelWindow)
					gtk.GDKGdk_window_resize(topLevelWindow, width, naturalHeight[0])
				}
			}
		}
	}
}

